import { GoogleGenAI } from "@google/genai";
import { AspectRatio, UploadedImage, FashionModelType, FashionAgeGroup, FashionStyle, MockupCategory } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function fileToGenerativePart(file: File): Promise<{ inlineData: { data: string; mimeType: string } }> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve({
        inlineData: {
          data: base64String,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function extractImagesFromResponse(response: any): string[] {
    const images: string[] = [];
    for (const candidate of response.candidates || []) {
        for (const candidatePart of candidate.content?.parts || []) {
            if (candidatePart.inlineData) {
                images.push(`data:image/png;base64,${candidatePart.inlineData.data}`);
            }
        }
    }
    return images;
}

// --- New Feature: Generate Idol Image (Celebrity Compositing) ---
export const generateIdolImage = async (
  userImage: UploadedImage,
  idolName: string,
  ratio: AspectRatio
): Promise<string[]> => {
  const userPart = await fileToGenerativePart(userImage.file);

  const systemPrompt = `
    TASK TYPE: High-fidelity photorealistic image generation.

    Create a hyper-realistic, professional photograph that looks like a real photo taken by a professional photographer.

    The image must show TWO people together in the same scene:

    1) The FIRST person is the individual from the uploaded photo (Image 1).
       - Preserve their facial identity accurately.
       - Maintain their real facial structure, skin tone, age, and gender.
       - Do NOT change their identity.
       - Do NOT beautify excessively.
       - Keep proportions natural and realistic.

    2) The SECOND person is the internationally famous celebrity: "${idolName}".
       - "${idolName}" MUST be clearly recognizable.
       - Their face must strongly resemble their real-world public appearance.
       - Facial features, eyes, nose, jawline, smile, hairstyle, and overall look should match how "${idolName}" is commonly known by the public.
       - This MUST look like "${idolName}", not a random person or a generic actor look.

    IMPORTANT VISUAL RULES:
    - Both people must appear in the SAME photo, not separate images.
    - Lighting must be consistent on both faces.
    - Skin tones must look natural.
    - Shadows and depth must match realistically.
    - The image must look like a real photograph, NOT an illustration, cartoon, painting, or AI art style.

    SCENE & STYLE:
    - Natural interaction between both people (standing side by side, friendly pose, casual photo together).
    - Realistic camera perspective.
    - Professional photography quality.
    - Sharp focus, high detail, natural colors.

    STRICTLY AVOID:
    - Cartoon, anime, or illustration style
    - Unrealistic beauty filters
    - Face distortion or identity mixing
    - Blurry, low-quality, or over-smoothed faces
    - Extra people in the image
    - Melted or fused facial features

    FINAL RESULT:
    The final image should look like an authentic real-life photo where the person from the uploaded image is genuinely taking a photo together with "${idolName}".
  `;

  try {
    const promises = Array.from({ length: 4 }).map(() => 
      ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [userPart, { text: systemPrompt }],
        },
        config: {
          imageConfig: { aspectRatio: ratio }
        }
      })
    );

