      INPUTS:
      - Image 1: PERSON A (The User). Preserve facial identity exactly.
      - Image 2: PERSON B (The Idol/Artist). Preserve facial identity exactly.

      SCENE STYLE: ${variation.style}
      INSTRUCTION: ${variation.instruction}

      STRICT IDENTITY CONSTRAINTS:
      - Person A's face MUST look exactly like Image 1.
      - Person B's face MUST look exactly like Image 2.
      - Do NOT mix their features.
      - Do NOT generate generic faces.

      VISUAL RULES:
      - Both people must appear in the SAME photo.
      - Consistent lighting and realistic shadows.
      - Natural skin tones.
      - Professional DSLR photography look (unless Selfie mode).

      FINAL RESULT:
      A believable real-world photo of Person A and Person B together.
    `;

    try {
       const response = await ai.models.generateContent({
          model: "gemini-2.5-flash-image",
          contents: {
            parts: [userPart, idolPart, { text: systemPrompt }],
          },
          config: {
            imageConfig: { aspectRatio: ratio },
          },
        });
        const images = extractImagesFromResponse(response);
        return images[0]; // Return single image per variation
    } catch (e) {
      console.error(`Error generating variation ${variation.style}:`, e);
      return null;
    }
  };

  try {
    // Generate all variations in parallel
    const results = await Promise.all(variations.map(v => generateVariation(v)));
    const validImages = results.filter((img): img is string => img !== null);

    if (validImages.length === 0) throw new Error("No image generated");

    return validImages;
  } catch (error) {
    console.error("Idol generation error:", error);
    throw error;
  }
};


